import React,{useState,useEffect,useMemo,useRef,useCallback} from 'react';
import {createRoot} from 'react-dom/client';
import {LayoutDashboard,ClipboardPenLine,ShoppingBag,Target,Package,Users,Settings,ChevronDown,ArrowUpRight,ArrowDownRight,ArrowRight,Plus,Search,Download,Menu,X,LogOut,Check,CheckCheck,CalendarDays,RefreshCw,Send,Save,ExternalLink,LockKeyhole,Leaf,SlidersHorizontal,FileText,Wallet,TrendingUp,MessageSquare,ChevronRight,Trash2,Pencil,Eye,AlertCircle,LoaderCircle} from 'lucide-react';
import {request,config,isConfigured,clearRequestState} from './api';
import {fields,money,pct,divide,dayString,previousDay,periodRange,aggregate,summarizeTargets,carryoverBefore,isCareOrder,orderWeight,countFormat,targetMath,netSpend,validateEntries} from './domain';
import './styles.css';
import DateField from './DateField.jsx';
import NumberField from './NumberField.jsx';
import BatchEntry from './BatchEntry.jsx';
import {OperationsProvider,useOperations,ActionButton,ActionForm} from './Operations.jsx';
import ReportList from './ReportList.jsx';
import ProductSummary from './ProductSummary.jsx';
import TargetsTable from './TargetsTable.jsx';
import OverviewPie from './OverviewPie.jsx';
import {productTone} from './palette.js';
import ReportHistory from './ReportHistory.jsx';
import WindowGate,{DataWindow} from './DataWindow.jsx';
import {containsRange,validRange,mergeDelta} from './data-window.js';
const nav=[['overview','Tổng quan',LayoutDashboard],['daily','Bảng điền hằng ngày',ClipboardPenLine],['submissions','Danh sách bảng',FileText],['orders','Đơn hàng',ShoppingBag],['targets','Mục tiêu tháng',Target],['products','Sản phẩm',Package],['accounts','Account & phân phối',Users]];
const number=n=>money(n);const inputNum=v=>Number(String(v).replace(/[^0-9.]/g,''))||0;
function Brand(){return <div className="brand"><span className="brand-icon"><Leaf size={22}/></span><span>Sổ Liệu<span className="brand-dot">.</span></span></div>}
function App(){
 const operations=useOperations();
 const epoch=useRef(0),sessionRef=useRef(null),dbRef=useRef(null),windowSeq=useRef(0),windowKey=useRef('');
 const [windowError,setWindowError]=useState('');
 const [session,setSession]=useState(null),[accessError,setAccessError]=useState('');
 useEffect(()=>{sessionStorage.removeItem('so-lieu.session');localStorage.removeItem('so-lieu.ui-user');localStorage.removeItem('so-lieu.demo.v1');},[]);
 function clearSession(){epoch.current++;windowSeq.current++;windowKey.current='';sessionRef.current=null;dbRef.current=null;clearRequestState();setWindowError('');sessionStorage.removeItem('so-lieu.session');localStorage.removeItem('so-lieu.ui-user');setSession(null);setDb(null);setPage('overview');setOpenReport(null);setError('');}
 function handleAccessError(e){if(!['FORBIDDEN','UNAUTHENTICATED'].includes(e.code))return false;clearSession();setAccessError(e.code==='FORBIDDEN'?'Không đủ quyền để thực hiện. Bạn đã được đăng xuất.':'Phiên đăng nhập không còn hợp lệ. Vui lòng đăng nhập lại.');return true;}
 const [db,setDb]=useState(null),[page,setPage]=useState('overview'),[openReport,setOpenReport]=useState(null),[mobile,setMobile]=useState(false),[toast,setToast]=useState(null),[loading,setLoading]=useState(false),[error,setError]=useState('');
 sessionRef.current=session;dbRef.current=db;
 const notify=(message,type='success')=>{setToast({message,type});setTimeout(()=>setToast(null),5000);};
 const ensureWindow=useCallback(async(range,force=false)=>{
  if(!sessionRef.current||!validRange(range))return;
  if(!force&&containsRange(dbRef.current?.scope,range)){if(windowKey.current&&windowKey.current!==range.join('|')){windowSeq.current++;windowKey.current='';}return;}
  const key=range.join('|');if(windowKey.current===key&&!force)return;windowKey.current=key;
  const generation=epoch.current,seq=++windowSeq.current,active=sessionRef.current;setWindowError('');
  try{const next=await request('bootstrap',{from:range[0],to:range[1]},active);if(generation===epoch.current&&seq===windowSeq.current){dbRef.current=next;setDb(next);setError('');}}
  catch(e){if(generation===epoch.current&&seq===windowSeq.current){if(!handleAccessError(e))setWindowError(e.message);}}
  finally{if(seq===windowSeq.current)windowKey.current='';}
 },[]);
 const loadHistory=useCallback(async(id,offset=0)=>{const generation=epoch.current;try{const data=await request('reportHistory',{id,offset},sessionRef.current);if(generation!==epoch.current)throw Error('Phiên đã thay đổi.');return data;}catch(e){if(generation===epoch.current)handleAccessError(e);throw e;}},[]);
 async function refresh(s=session){return operations.run('Đang tải dữ liệu…',async()=>{const generation=epoch.current,seq=++windowSeq.current;setLoading(true);try{const next=await request('bootstrap',dbRef.current?.scope||{},s);if(generation===epoch.current&&seq===windowSeq.current){windowKey.current='';dbRef.current=next;setDb(next);setError('');setWindowError('');}}catch(e){if(generation===epoch.current&&!handleAccessError(e))setError(e.message);}finally{setLoading(false);}});}
 useEffect(()=>{if(session&&!db)refresh(session);},[session?.token]);
 async function mutate(action,payload){return operations.run(action==='saveReport'?(payload.status==='submitted'?'Đang gửi báo cáo…':'Đang lưu bản nháp…'):action==='deleteOrder'?'Đang xóa đơn hàng…':action==='saveOrder'?'Đang lưu đơn hàng…':'Đang lưu thay đổi…',async()=>{const generation=epoch.current;windowSeq.current++;windowKey.current='';setLoading(true);try{const next=await request(action,payload,session);if(generation!==epoch.current)return false;const merged=mergeDelta(dbRef.current,next);dbRef.current=merged;setDb(merged);return true;}catch(e){if(generation===epoch.current&&!handleAccessError(e))notify(e.message,'error');return false;}finally{setLoading(false);}});}

 function logout(){const old=session;clearSession();void request('logout',{},old).catch(()=>{});}
 if(!session)return <><Login onLogin={s=>{const safe={token:s.token,user:{id:s.user.id}};epoch.current++;clearRequestState();sessionRef.current=safe;localStorage.setItem('so-lieu.ui-user',JSON.stringify(s.user));if(s.db){dbRef.current=s.db;setDb(s.db);}setError('');setSession(safe);}}/>{accessError&&<div className="modal-backdrop"><section className="modal" role="alertdialog" aria-modal="true" aria-label="Không đủ quyền"><h2>Không thể thực hiện</h2><p>{accessError}</p><div className="modal-actions"><button autoFocus className="btn primary" onClick={()=>setAccessError('')}>Đăng nhập lại</button></div></section></div>}</>;
 if(!db)return <div className="bootstrap-state"><Brand/>{error?<><AlertCircle size={28}/><h2>Chưa xác minh được phiên đăng nhập</h2><p>{error}</p><ActionButton className="btn primary" onClick={()=>refresh()}>Thử lại</ActionButton><ActionButton className="btn" onClick={logout}>Đăng xuất</ActionButton></>:<><LoaderCircle className="spin" size={28}/><p>Đang xác minh tài khoản với máy chủ…</p></>}</div>;
 const verified=db.viewer||db.accounts.find(a=>a.id===session.user?.id);
 let user=verified;try{const hint=JSON.parse(localStorage.getItem('so-lieu.ui-user'));if(hint?.id===verified?.id&&['admin','user'].includes(hint.role))user={...verified,role:hint.role};}catch{}
 if(!user)return <div className="bootstrap-state"><AlertCircle/><p>Phiên đăng nhập không hợp lệ. Vui lòng đăng nhập lại.</p><ActionButton className="btn" onClick={logout}>Đăng xuất</ActionButton></div>;
 const isAdmin=user.role==='admin';const items=nav.filter(n=>isAdmin?n[0]!=='daily':!['products','accounts','settings'].includes(n[0]));
 return <DataWindow.Provider value={{scope:db.scope,error:windowError,ensure:ensureWindow,history:loadHistory}}><div className="app-shell">
  {mobile&&<div className="scrim" onClick={()=>setMobile(false)}/>}
  <aside className={'sidebar '+(mobile?'open':'')}><Brand/><ActionButton className="workspace"><span className="workspace-avatar">SL</span><span><small>{isAdmin?'Quản trị viên':'Tài khoản thành viên'}</small></span><ChevronDown size={15}/></ActionButton><div className="nav-label">KHÔNG GIAN LÀM VIỆC</div><nav>{items.map(([id,label,Icon])=><ActionButton className={'nav-item '+(page===id?'active':'')} key={id} onClick={()=>{setPage(id);if(id==='daily')setOpenReport(null);setMobile(false);}}><Icon size={19}/><span>{label}</span>{id==='daily'&&db&&<em>{db.reports.filter(r=>r.status==='draft').length||''}</em>}</ActionButton>)}</nav><div className="sidebar-bottom"><ActionButton className="profile" onClick={logout}><span className="avatar">{user.ownerName.split(' ').map(x=>x[0]).slice(0,2).join('')}</span><span><b>{user.ownerName}</b><small>{isAdmin?'Admin':'User'} · Đăng xuất</small></span><LogOut size={16}/></ActionButton></div></aside>
  <div className="main-shell"><header className="topbar"><div className="breadcrumb"><ActionButton className="icon-btn mobile-toggle" onClick={()=>setMobile(true)} aria-label="Mở menu"><Menu size={22}/></ActionButton><span>Không gian làm việc</span><ChevronRight size={14}/><b>{nav.find(n=>n[0]===page)?.[1]}</b></div><div className="topbar-right"><span className="mode-badge live">Google Sheets</span><ActionButton className="icon-btn" onClick={()=>refresh()} title="Tải lại dữ liệu"><RefreshCw size={17} className={loading?'spin':''}/></ActionButton><span className="mini-avatar">{user.ownerName.charAt(0)}</span></div></header>
  <main>{error?<div className="empty panel"><AlertCircle/><h2>Chưa tải được dữ liệu</h2><p>{error}</p><ActionButton className="btn primary" onClick={()=>refresh()}>Thử lại</ActionButton></div>:!db?<div className="loading">Đang tải không gian làm việc…</div>:<>
  {page==='overview'&&<Overview db={db} user={user} notify={notify} setPage={setPage} mutate={mutate}/>}
  {page==='daily'&&<Daily key={openReport?.id||'new'} initial={openReport} db={db} user={user} mutate={mutate} notify={notify} busy={loading}/>}
  {page==='submissions'&&<ReportList FilterComponent={Filters} db={db} user={user} mutate={mutate} notify={notify} busy={loading} onOpen={r=>{setOpenReport(r);setPage('daily');}}/>}
  {page==='orders'&&<Orders db={db} user={user} mutate={mutate} notify={notify} busy={loading}/>}
  {page==='targets'&&<Targets db={db} user={user} mutate={mutate} notify={notify}/>}
  {page==='products'&&isAdmin&&<Products db={db} mutate={mutate} notify={notify}/>}
  {page==='accounts'&&isAdmin&&<Accounts db={db} mutate={mutate} notify={notify}/>}
  {page==='settings'&&isAdmin&&<SettingsPage/>}
  </>}</main><footer>Sổ Liệu <span>•</span> Dữ liệu rõ ràng. Quyết định vững vàng.<span className="footer-right">Kết nối Google Sheets</span></footer></div>
  {toast&&<div role="status" className={'toast '+toast.type}>{toast.type==='error'?<AlertCircle size={18}/>:<CheckCheck size={18}/>} {toast.message}<ActionButton onClick={()=>setToast(null)} aria-label="Đóng"><X size={15}/></ActionButton></div>}
 </div></DataWindow.Provider>
}
function Login({onLogin}){
 const operations=useOperations(),[form,setForm]=useState({username:'',password:''}),[busy,setBusy]=useState(false),[error,setError]=useState('');
 async function login(e){e.preventDefault();if(!isConfigured)return;const next=await operations.run('Đang đăng nhập…',async()=>{setBusy(true);setError('');try{return await request('login',form);}catch(e){setError(e.message);return false;}finally{setBusy(false);}});if(next)onLogin(next);}
 return <div className="login"><section className="login-story"><Brand/><div><span className="eyebrow light">MỖI CON SỐ, MỘT BƯỚC TIẾN</span><h1>Nhìn rõ hôm nay.<br/>Chủ động ngày mai.</h1><p>Một không gian cho dữ liệu, đội ngũ<br/>và những mục tiêu cùng nhau chinh phục.</p></div><small>SỔ LIỆU / BUSINESS WORKSPACE</small></section><section className="login-form"><div className="login-card"><span className="eyebrow">CHÀO MỪNG TRỞ LẠI</span><h2>Đăng nhập</h2><p>Sử dụng tài khoản và mật khẩu do admin cấp.</p>{!isConfigured&&<p className="info-note" role="alert">Chưa cấu hình kết nối máy chủ. Chủ web cần điền URL Apps Script /exec trong config.js hoặc SO_LIEU_API_URL trên Vercel rồi triển khai lại.</p>}<ActionForm onSubmit={login}><label>Tên đăng nhập<input required maxLength={60} autoComplete="username" value={form.username} onChange={e=>setForm({...form,username:e.target.value})}/></label><label>Mật khẩu<input type="password" minLength={8} maxLength={200} required autoComplete="current-password" value={form.password} onChange={e=>setForm({...form,password:e.target.value})}/></label>{error&&<p className="error-text" role="alert">{error}</p>}<ActionButton className="btn primary login-submit" disabled={busy||!isConfigured}>{busy?'Đang đăng nhập…':'Đăng nhập'}<ArrowRight size={18}/></ActionButton></ActionForm><div className="login-secure"><LockKeyhole size={14}/> Mỗi account, một không gian dữ liệu riêng.</div></div></section></div>;
}

function Heading({eyebrow='KHÔNG GIAN KINH DOANH',title,description,children}){return <div className="page-heading"><div><div className="eyebrow">{eyebrow}</div><h1>{title}</h1><p>{description}</p></div><div className="heading-actions">{children}</div></div>}
function Filters({db,user,filter,setFilter}){return <div className="filterbar"><div className="segmented">{[['day','Từng ngày'],['range','Khoảng ngày'],['month','Theo tháng']].map(([v,l])=><ActionButton key={v} className={filter.mode===v?'selected':''} onClick={()=>setFilter({...filter,mode:v})}>{l}</ActionButton>)}</div><div className="date-fields"><CalendarDays size={16}/>{filter.mode==='day'?<DateField aria-label="Ngày báo cáo" type="date" value={filter.date} onChange={e=>setFilter({...filter,date:e.target.value})}/>:filter.mode==='month'?<DateField aria-label="Tháng báo cáo" type="month" value={filter.month} onChange={e=>setFilter({...filter,month:e.target.value})}/>:<><DateField aria-label="Từ ngày" type="date" value={filter.from} onChange={e=>setFilter({...filter,from:e.target.value})}/><span>→</span><DateField aria-label="Đến ngày" type="date" min={filter.from} value={filter.to} onChange={e=>setFilter({...filter,to:e.target.value})}/></>}</div><div className="filter-spacer"/>{user.role==='admin'&&<select aria-label="Chọn account" value={filter.account} onChange={e=>setFilter({...filter,account:e.target.value})}><option value="all">Tất cả account</option>{db.accounts.filter(a=>a.role==='user').map(a=><option key={a.id} value={a.id}>{a.ownerName}</option>)}</select>}<select aria-label="Chọn sản phẩm" value={filter.product} onChange={e=>setFilter({...filter,product:e.target.value})}><option value="all">Tất cả sản phẩm</option>{db.products.map(p=><option key={p.id} value={p.id}>{p.name}</option>)}</select></div>}
function exportCsv(rows,db){const header=['Ngày','Chủ sở hữu','Sản phẩm','Chi thực tế','Tổng data','Đơn TC','Doanh thu bán hàng','Doanh thu chăm'];const data=rows.map(r=>[r.date,db.accounts.find(a=>a.id===r.accountId)?.ownerName,db.products.find(p=>p.id===r.productId)?.name,r.spend,r.data,r.success,r.revenue,r.care]);const csv='\uFEFF'+[header,...data].map(row=>row.map(v=>'"'+String(/^[=+@\t\r-]/.test(String(v??''))?"'"+v:v??'').replaceAll('"','""')+'"').join(',')).join('\r\n');const link=document.createElement('a');link.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8;'}));link.download='so-lieu-bao-cao.csv';link.click();URL.revokeObjectURL(link.href);}
function Overview({db,user,notify,setPage,mutate}){
 const today=dayString(),defaultDate=user.role==='admin'?previousDay():today;const [filter,setFilter]=useState({mode:user.role==='admin'?'day':'month',date:defaultDate,from:defaultDate.slice(0,7)+'-01',to:defaultDate,month:defaultDate.slice(0,7),account:user.role==='admin'?'all':user.id,product:'all'}),[tab,setTab]=useState('products'),[showCharts,setShowCharts]=useState(false);
 const range=periodRange(filter.mode,filter.date,filter.from,filter.to,filter.month);const result=aggregate(db,range,filter.account,filter.product);const {total}=result;
 const relevantProducts=db.products.filter(p=>filter.product==='all'||p.id===filter.product);
 const series=Array.from({length:Math.min(367,Math.max(0,Math.round((new Date(range[1]>today&&range[0]<=today?today:range[1])-new Date(range[0]))/86400000)+1))},(_,i)=>{const d=new Date(range[0]+'T00:00:00Z');d.setUTCDate(d.getUTCDate()+i);const date=d.toISOString().slice(0,10);const day=result.detail.filter(r=>r.date===date);return {date,revenue:day.reduce((s,r)=>s+r.revenue,0),spend:day.reduce((s,r)=>s+r.spend,0)};});
 const max=Math.max(...series.map(s=>Math.max(s.revenue,s.spend)),1);const points=key=>series.map((s,i)=>`${55+i*(830/Math.max(series.length-1,1))},${185-s[key]/max*145}`).join(' ');
 const pending=db.reports.filter(r=>r.status==='draft'&&r.date===today&&(filter.account==='all'||r.accountId===filter.account));
 return <><Heading title={user.role==='admin'?'Tổng quan kinh doanh':'Chào '+user.ownerName.split(' ')[0]+', một ngày hiệu quả.'} description="Một góc nhìn đầy đủ về hiệu suất và những bước tiến của đội ngũ."><ActionButton className="btn primary" aria-haspopup="dialog" onClick={()=>setShowCharts(true)}><TrendingUp size={18}/> Xem biểu đồ</ActionButton><ActionButton className="btn" onClick={()=>exportCsv(result.detail,db)}><Download size={16}/> Xuất báo cáo</ActionButton>{user.role!=='admin'&&<ActionButton className="btn primary" onClick={()=>setPage('daily')}><Plus size={17}/> Điền báo cáo</ActionButton>}</Heading>
 <Filters {...{db,user,filter,setFilter}}/>{range[0]>range[1]&&<div className="error-text">Ngày bắt đầu phải trước hoặc bằng ngày kết thúc.</div>}
 <WindowGate range={range}><section className="stats">{[{label:'Doanh thu bán hàng',value:money(total.revenue),unit:'đ',icon:TrendingUp,sub:'Doanh thu chăm: '+money(total.care)+'đ',tone:'green'},{label:'Chi thực tế',value:money(total.spend),unit:'đ',icon:Wallet,sub:'Ngân sách đầu ngày − thừa cuối ngày',tone:'blue'},{label:'Tổng data',value:money(total.data),unit:'',icon:MessageSquare,sub:'Chi phí mess: '+money(result.costPerData)+'đ / data',tone:'amber'},{label:'Tỷ lệ chi phí / DS',value:pct(result.costRatio),unit:'',icon:SlidersHorizontal,sub:'Đơn TC: '+countFormat(total.success)+' · Upsale: '+countFormat(total.upsale),tone:'purple'}].map(s=><article className="stat" key={s.label} style={{background:productTone(s.label).background,color:productTone(s.label).text,borderColor:productTone(s.label).border}}><div className="stat-top"><span>{s.label}</span><span className={'stat-icon '+s.tone}><s.icon size={17}/></span></div><div className="stat-value">{s.value}<small>{s.unit}</small></div><div className="stat-sub">{s.sub}</div></article>)}</section>
 {showCharts&&<Modal title="Biểu đồ tổng quan" className="charts-modal" onClose={()=>setShowCharts(false)}><p className="charts-period">{range.map(d=>d.split('-').reverse().join('/')).join(' – ')} · {filter.account==='all'?'Tất cả account':db.accounts.find(a=>a.id===filter.account)?.ownerName}</p><section className="charts-row"><article className="panel revenue-panel"><div className="panel-heading"><div><h2>Nhịp kinh doanh</h2><p>Doanh thu và chi thực tế trong thời gian đã chọn</p></div><div className="legend"><span><i/>Doanh thu</span><span><i className="soft"/>Chi thực tế</span></div></div><div className="chart-wrap"><svg viewBox="0 0 925 230" role="img" aria-label="Biểu đồ doanh thu bán hàng và chi thực tế"><defs><linearGradient id="area" x1="0" x2="0" y1="0" y2="1"><stop offset="0%" stopColor="#28856b" stopOpacity=".17"/><stop offset="100%" stopColor="#28856b" stopOpacity="0"/></linearGradient></defs>{[0,1,2,3].map(i=><g key={i}><line x1="55" x2="900" y1={40+i*48} y2={40+i*48} stroke="#edf0ed" strokeDasharray="4 5"/><text x="43" y={44+i*48} textAnchor="end" fill="#929b96" fontSize="11">{money(max*(1-i/3)/1000000)}tr</text></g>)}{series.length>0&&<><polygon points={`55,185 ${points('revenue')} ${55+(series.length-1)*830/Math.max(series.length-1,1)},185`} fill="url(#area)"/><polyline points={points('revenue')} fill="none" stroke="#18765c" strokeWidth="3" strokeLinejoin="round"/><polyline points={points('spend')} fill="none" stroke="#b8c8bd" strokeWidth="2.5" strokeDasharray="5 5"/>{series.length===1&&<>{['revenue','spend'].map((key,i)=><circle key={key} cx="55" cy={185-series[0][key]/max*145} r={i?4:6} fill={i?'#748b7a':'#18765c'}><title>{key==='revenue'?'Doanh thu':'Chi thực tế'}: {money(series[0][key])}đ</title></circle>)}</>}{series.filter((_,i)=>i===0||i===series.length-1||i%Math.max(1,Math.ceil(series.length/6))===0).map(s=>{const i=series.indexOf(s);return <text key={s.date} x={55+i*830/Math.max(series.length-1,1)} y="216" textAnchor="middle" fill="#8b9690" fontSize="11">{s.date.slice(8)}/{s.date.slice(5,7)}</text>})}</>}</svg></div></article>{user.role==='admin'?<OverviewPie products={relevantProducts} detail={result.detail}/>:<article className="panel mix-panel"><div className="panel-heading"><div><h2>Cơ cấu doanh thu</h2><p>Theo từng sản phẩm</p></div><Package size={17} color="#8c9791"/></div><div className="mix-total"><span>{money(total.revenue)}</span><small>đ doanh thu bán hàng</small></div><div className="mix-bar">{relevantProducts.map(p=>{const revenue=result.detail.filter(r=>r.productId===p.id).reduce((s,r)=>s+r.revenue,0);return <div key={p.id} style={{width:(divide(revenue,total.revenue)*100)+"%",background:productTone(p.id).color}}/>})}</div><div className="mix-items">{relevantProducts.map(p=>{const sum=result.detail.filter(r=>r.productId===p.id).reduce((s,r)=>s+r.revenue,0);return <div key={p.id}><span><i style={{background:productTone(p.id).color}}/>{p.name}</span><b>{pct(divide(sum,total.revenue))}</b></div>})}</div></article>}</section></Modal>}
 <ProductSummary db={db} range={range} account={filter.account} product={filter.product}/><section className="panel report-panel"><div className="panel-heading"><div><h2>Hiệu suất chi tiết</h2><p>{result.accountDays} lượt account-ngày đã gửi · Cập nhật theo dữ liệu đã lưu</p></div><div className="segmented small">{[['products','Sản phẩm'],['accounts','Account'],['daily','Từng ngày']].filter(x=>user.role==='admin'||x[0]!=='accounts').map(([v,l])=><ActionButton key={v} className={tab===v?'selected':''} onClick={()=>setTab(v)}>{l}</ActionButton>)}</div></div><div className="table-scroll"><table><thead><tr><th>{tab==='products'?'Sản phẩm':tab==='accounts'?'Chủ sở hữu':'Ngày / Chủ sở hữu'}</th><th>Chi thực tế</th><th>Tổng data</th><th>Chi phí mess</th><th>Đơn TC</th><th>Doanh thu</th><th>DT chăm</th><th>Chi phí/DS</th></tr></thead><tbody>{(tab==='daily'?result.detail:(tab==='products'?relevantProducts:db.accounts.filter(a=>a.role==='user')).map(x=>{const rr=result.detail.filter(r=>tab==='products'?r.productId===x.id:r.accountId===x.id);return {id:x.id,label:x.name||x.ownerName,...rr.reduce((a,r)=>{for(const k of ['spend','data','success','revenue','care'])a[k]+=r[k];return a;},{spend:0,data:0,success:0,revenue:0,care:0}),color:x.color};})).map((r,i)=><tr key={r.id||i}><td><span className="product-cell"><i style={{background:productTone(r.productId||r.id||i).color}}/>{tab==='daily'?<span>{r.date.split('-').reverse().join('/')}<small>{db.accounts.find(a=>a.id===r.accountId)?.ownerName} · {db.products.find(p=>p.id===r.productId)?.name}{!r.submitted?' · Chỉ có đơn hàng':''}</small></span>:r.label}</span></td><td>{money(r.spend)}</td><td>{money(r.data)}</td><td>{money(divide(r.spend,r.data))}</td><td>{countFormat(r.success)}</td><td className="strong">{money(r.revenue)}</td><td>{money(r.care)}</td><td><span className={'ratio '+(divide(r.spend,r.revenue)>.4?'warning':'')}>{pct(divide(r.spend,r.revenue))}</span></td></tr>)}</tbody><tfoot><tr><td>Tổng cộng</td><td>{money(total.spend)}</td><td>{money(total.data)}</td><td>{money(result.costPerData)}</td><td>{countFormat(total.success)}</td><td>{money(total.revenue)}</td><td>{money(total.care)}</td><td>{pct(result.costRatio)}</td></tr><tr className="average"><td>TB / {filter.account==='all'?'account-ngày':'ngày đã gửi'}</td><td>{money(divide(total.spend,result.accountDays))}</td><td>{money(divide(total.data,result.accountDays))}</td><td>{money(result.costPerData)}</td><td>{countFormat(divide(total.success,result.accountDays))}</td><td>{money(divide(result.averageTotal.revenue,result.accountDays))}</td><td>{money(divide(result.averageTotal.care,result.accountDays))}</td><td>{pct(result.costRatio)}</td></tr></tfoot></table></div><div className="table-note"><span><i/> Chỉ tiêu chi phí và tỷ lệ được tính từ tổng, không cộng trung bình các tỷ lệ.</span><span>Đơn vị tiền: VNĐ</span></div></section>
 <section className="bottom-grid"><div className="panel submission-panel"><div className="panel-heading"><div><h2>{user.role==='admin'?'Nhịp gửi báo cáo hôm qua':'Nhịp gửi báo cáo hôm nay'}</h2><p>{defaultDate.split('-').reverse().join('/')}</p></div><span className="tag">{db.reports.filter(r=>r.date===defaultDate&&r.status==='submitted').length} đã gửi</span></div>{db.accounts.filter(a=>a.role==='user'&&(filter.account==='all'||a.id===filter.account)).map(a=>{const r=db.reports.find(r=>r.accountId===a.id&&r.date===defaultDate);return <div className="submission-row" key={a.id}><span className="avatar small-avatar">{a.ownerName[0]}</span><div><b>{a.ownerName}</b><small>{db.assignments.filter(x=>x.active&&x.accountId===a.id).length} sản phẩm được giao</small></div><span className={'status '+(r?.status==='submitted'?'done':'draft')}>{r?.status==='submitted'?<Check size={12}/>:null}{r?.status==='submitted'?'Đã gửi':r?'Bản nháp':'Chưa gửi'}</span>{user.role==='admin'&&r?.status==='submitted'&&<ActionButton className="text-btn" onClick={async()=>{if(await mutate('reopen',{id:r.id}))notify('Đã mở lại bảng để user chỉnh sửa.');}}>Mở lại</ActionButton>}</div>})}</div><div className="goal-callout"><span className="eyebrow">ĐI CÙNG MỤC TIÊU</span><h2>Mỗi ngày một bước.<br/>Mỗi tháng một cột mốc.</h2><p>Theo dõi doanh thu bán hàng và chăm sóc,<br/>để biết chính xác mình đang ở đâu.</p><ActionButton className="btn" onClick={()=>setPage('targets')}>Xem mục tiêu tháng <ArrowUpRight size={17}/></ActionButton><Target className="callout-icon" size={130}/></div></section>
 </WindowGate></>
}
function Daily({db,user,mutate,notify,busy,initial}){
 const [date,setDate]=useState(initial?.date||previousDay()),[account,setAccount]=useState(initial?.accountId||(user.role==='admin'?db.accounts.find(a=>a.role==='user')?.id:user.id)),[entries,setEntries]=useState([]),[confirm,setConfirm]=useState(false),[dirty,setDirty]=useState(false),[history,setHistory]=useState(false);
 const record=db.reports.find(r=>r.accountId===account&&r.date===date);const allowed=db.assignments.filter(a=>a.active&&a.accountId===account&&db.products.some(p=>p.id===a.productId&&p.active)).map(a=>a.productId);const locked=false;const submitted=record?.status==='submitted';
 useEffect(()=>{const ids=[...new Set([...allowed,...(record?.entries||[]).map(e=>e.productId)])];setEntries(ids.map(productId=>record?.entries.find(e=>e.productId===productId)||{productId,...Object.fromEntries(fields.map(([k])=>[k,0])),received:0}));setDirty(false);},[account,date,record?.revision,JSON.stringify(allowed)]);
 useEffect(()=>{const fn=e=>{if(dirty){e.preventDefault();e.returnValue='';}};window.addEventListener('beforeunload',fn);return()=>window.removeEventListener('beforeunload',fn);},[dirty]);
 const dailyCounts=aggregate(db,[date,date],account);
 const calculatedEntries=entries.map(e=>{const rows=dailyCounts.detail.filter(r=>r.productId===e.productId);const carry=carryoverBefore(db.reports,account,e.productId,date);const budgetFields=e.received!==undefined?{carryover:carry.amount,budget:carry.amount+Number(e.received||0)}:{};return {...e,...budgetFields,success:rows.reduce((n,r)=>n+r.success,0),upsale:rows.reduce((n,r)=>n+r.upsale,0)};});
 const update=(id,key,value)=>{setEntries(entries.map(e=>e.productId===id?{...e,[key]:inputNum(value)}:e));setDirty(true);};
 async function persist(status){try{validateEntries(calculatedEntries);}catch(e){notify(e.message,'error');return;}if(await mutate('saveReport',{accountId:account,date,entries:calculatedEntries,status,revision:record?.revision||0})){notify(status==='submitted'?'Đã gửi bảng ngày '+date.split('-').reverse().join('/')+'.':'Đã lưu bản nháp.');setConfirm(false);setDirty(false);}}
 return <><Heading eyebrow="NHẬP LIỆU" title="Bảng điền hằng ngày" description="Chọn ngày, điền sản phẩm được giao và gửi báo cáo khi đã hoàn tất."><span className={'status '+(submitted?'done':'draft')}>{submitted?'Đã gửi · Có thể sửa':dirty?'Có thay đổi chưa lưu':'Bản nháp'}</span></Heading><div className="panel entry-toolbar"><label>Ngày báo cáo<DateField type="date" value={date} onChange={e=>{if(!dirty||window.confirm('Có thay đổi chưa lưu. Chuyển ngày?'))setDate(e.target.value);}}/></label>{user.role==='admin'&&<label>Account<select value={account} onChange={e=>setAccount(e.target.value)}>{db.accounts.filter(a=>a.role==='user').map(a=><option value={a.id} key={a.id}>{a.ownerName}</option>)}</select></label>}<div className="entry-meta"><b>{db.accounts.find(a=>a.id===account)?.ownerName}</b><span>{entries.length} sản phẩm · {submitted?'Chỉnh số liệu rồi bấm Lưu thay đổi':'Nhập 0 nếu không phát sinh'}</span></div></div>
 <WindowGate range={[date,date]}>{user.role==='admin'&&!record?<div className="panel empty"><FileText/><h2>Admin chỉ xem và sửa bảng đã có</h2><p>Chọn một bảng trong Danh sách bảng để chỉnh sửa.</p></div>:entries.length===0?<div className="panel empty"><Package/><h2>Chưa được phân phối sản phẩm</h2><p>Admin cần giao sản phẩm cho account này trước khi điền bảng.</p></div>:<><div className="entry-grid">{calculatedEntries.map(e=>{const p=db.products.find(p=>p.id===e.productId);const canEdit=user.role==='admin'||(p?.active&&db.assignments.some(a=>a.active&&a.accountId===account&&a.productId===e.productId));const transfer=carryoverBefore(db.reports,account,e.productId,date);const previous=transfer.date?{date:transfer.date}:null;const balance=transfer.amount;const orders=db.orders.filter(o=>o.accountId===account&&o.date===date&&o.productId===e.productId&&!isCareOrder(o)&&!o.isBounced);return <section className="panel entry-card" key={e.productId}><div className="entry-card-head"><span className="product-mark" style={{background:p?.color||'#18765c'}}>{p?.name.charAt(0)}</span><div><h2>{p?.name}</h2><p>{previous?'Dư gần nhất: '+money(balance)+'đ · '+previous.date.split('-').reverse().join('/'):'Chưa có số dư ngày trước'}</p></div></div><div className="entry-fields">{e.received!==undefined&&<><label>Dư chuyển sang<input type="text" readOnly value={money(e.carryover)} disabled/><small>Giữ đến lần nhập tiếp theo, kể cả bỏ trống nhiều ngày</small></label><label>Tiền mới nhận<NumberField type="number" min="0" step="1" inputMode="numeric" disabled={locked||busy||!canEdit} value={e.received} onFocus={ev=>ev.target.select()} onChange={ev=>update(e.productId,'received',ev.target.value)}/><small>Chỉ nhập tiền nhận thêm, không nhập lại số dư</small></label></>}{fields.map(([k,l])=><label key={k}>{k==='budget'&&e.received!==undefined?'Tổng ngân sách khả dụng':l}<NumberField type="number" min="0" step="1" inputMode="numeric" disabled={locked||busy||!canEdit||['success','upsale'].includes(k)||(k==='budget'&&e.received!==undefined)} value={e[k]} onFocus={ev=>ev.target.select()} onChange={ev=>update(e.productId,k,ev.target.value)}/>{['success','upsale'].includes(k)&&<small>Tự cộng từ đơn hàng · Chia đơn = 0,5</small>}{k==='budget'&&<small>{e.received!==undefined?'Tự tính: dư chuyển sang + tiền mới nhận':'Bảng cũ: tổng ngân sách đã gồm tiền dư, không cộng thêm'}</small>}</label>)}</div><div className="calculated"><div><span>Chi thực tế</span><b>{money(netSpend(e))}đ</b></div><div><span>Chi phí mess</span><b>{money(divide(netSpend(e),e.data))}đ</b></div><div><span>Doanh thu bán hàng</span><b>{money(orders.reduce((a,o)=>a+o.amountVnd,0))}đ</b></div></div></section>})}</div><div className="sticky-actions"><span><LockKeyhole size={15}/>{dirty?'Chưa lưu thay đổi':submitted?'Có thể sửa bảng. Mỗi lần lưu đều có lịch sử.':'Chọn Lưu nháp hoặc Gửi bảng để lưu dữ liệu.'}</span><div>{user.role==='admin'&&record&&<ActionButton className="btn" onClick={()=>setHistory(true)}><FileText size={16}/> Lịch sử sửa</ActionButton>}{!submitted&&<ActionButton className="btn" disabled={busy} onClick={()=>persist('draft')}><Save size={16}/> Lưu nháp</ActionButton>}<ActionButton className="btn primary" disabled={busy} onClick={()=>{if(submitted){persist('submitted');return;}try{validateEntries(calculatedEntries);setConfirm(true);}catch(e){notify(e.message,'error');}}}><Save size={16}/>{submitted?'Lưu thay đổi':'Gửi bảng'}</ActionButton></div></div></>}
 {confirm&&<Modal title="Gửi bảng báo cáo?" onClose={()=>setConfirm(false)}><p>Báo cáo ngày <b>{date.split('-').reverse().join('/')}</b> của <b>{db.accounts.find(a=>a.id===account)?.ownerName}</b> có {entries.length} sản phẩm. Sau khi gửi vẫn có thể sửa. Admin xem được lịch sử thay đổi.</p><div className="modal-actions"><ActionButton className="btn" onClick={()=>setConfirm(false)}>Kiểm tra lại</ActionButton><ActionButton className="btn primary" disabled={busy} onClick={()=>persist('submitted')}>{busy?'Đang gửi…':'Xác nhận gửi'}</ActionButton></div></Modal>}
 {history&&record&&<ReportHistory db={db} report={record} onClose={()=>setHistory(false)}/>}</WindowGate>
 </>
}
function Modal({title,onClose,children,className=''}){const dialog=useRef(null);useEffect(()=>{const previous=document.activeElement,overflow=document.body.style.overflow;document.body.style.overflow='hidden';dialog.current?.querySelector('button')?.focus();const fn=e=>{if(e.key==='Escape'){e.preventDefault();onClose();}if(e.key==='Tab'){const items=[...dialog.current.querySelectorAll('button:not(:disabled),select:not(:disabled),input:not(:disabled),[tabindex="0"]')].filter(x=>x.getClientRects().length),first=items[0],last=items[items.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}};window.addEventListener('keydown',fn);return()=>{window.removeEventListener('keydown',fn);document.body.style.overflow=overflow;previous?.focus();};},[]);return <div className="modal-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)onClose();}}><section ref={dialog} className={'modal '+className} role="dialog" aria-modal="true" aria-label={title}><div className="modal-heading"><h2>{title}</h2><ActionButton className="icon-btn" onClick={onClose} aria-label="Đóng"><X size={20}/></ActionButton></div>{children}</section></div>}
function Orders({db,user,mutate,notify,busy}){
 const [filter,setFilter]=useState({mode:'day',date:previousDay(),from:previousDay().slice(0,7)+'-01',to:previousDay(),month:previousDay().slice(0,7),account:'all',product:'all'});
 const orderRange=periodRange(filter.mode,filter.date,filter.from,filter.to,filter.month);
 const [orderKind,setOrderKind]=useState('all');
 const [search,setSearch]=useState(''),[month,setMonth]=useState(previousDay().slice(0,7)),[form,setForm]=useState(null),[deleting,setDeleting]=useState(null),[batch,setBatch]=useState(false);
 const assigned=user.role==='admin'?db.products.filter(p=>p.active):db.products.filter(p=>p.active&&db.assignments.some(a=>a.accountId===user.id&&a.productId===p.id&&a.active));
 const orders=db.orders.filter(o=>(orderKind==='all'||(orderKind==='care'?isCareOrder(o):!isCareOrder(o)))&&(user.role==='admin'?(o.date>=orderRange[0]&&o.date<=orderRange[1]&&(filter.account==='all'||o.accountId===filter.account)&&(filter.product==='all'||o.productId===filter.product)):o.date.startsWith(month))&&(!search||[o.customerName,db.products.find(p=>p.id===o.productId)?.name,db.accounts.find(a=>a.id===o.accountId)?.ownerName].join(' ').toLowerCase().includes(search.toLowerCase()))).sort((a,b)=>b.date.localeCompare(a.date));
 function add(){const p=assigned[0];if(!p){notify('Chưa có sản phẩm được phân phối.','error');return;}if(window.matchMedia('(min-width: 769px)').matches){setBatch(true);return;}setForm({date:previousDay(),accountId:user.role==='admin'?db.accounts.find(a=>a.role==='user')?.id:user.id,productId:'',customerName:'',amountUsd:'',rate:p.rate,type:'sale'});}
 return <><Heading eyebrow="DOANH THU" title="Đơn hàng" description="Bảng đơn riêng: nhập số tiền thực tế của từng đơn. Báo cáo tự lấy theo ngày, account và sản phẩm.">{user.role!=='admin'&&<ActionButton className="btn primary" onClick={add}><Plus size={17}/> Thêm đơn hàng</ActionButton>}</Heading>{user.role==='admin'&&<Filters {...{db,user,filter,setFilter}}/>}<WindowGate range={user.role==='admin'?orderRange:periodRange('month','','','',month)}><div className="panel"><div className="list-toolbar"><div className="search-input"><Search size={17}/><input placeholder="Tìm khách hàng, sản phẩm, account…" value={search} onChange={e=>setSearch(e.target.value)}/></div>{user.role==='admin'&&<label className="order-kind-filter">Loại đơn<select aria-label="Lọc loại đơn hàng" value={orderKind} onChange={e=>setOrderKind(e.target.value)}><option value="all">Tất cả đơn hàng</option><option value="sale">Đơn bán hàng</option><option value="care">Đơn chăm sóc (gồm Upsale)</option></select></label>}{user.role!=='admin'&&<DateField type="month" aria-label="Tháng đơn hàng" value={month} onChange={e=>setMonth(e.target.value)}/>}<span className="tag">{orders.length} bản ghi · {countFormat(orders.reduce((n,o)=>n+orderWeight(o),0))} đơn quy đổi</span></div><div className="table-scroll"><table><thead><tr><th>Ngày / Khách hàng</th><th>Chủ sở hữu</th><th>Sản phẩm</th><th>Loại doanh thu</th><th>Số đơn</th><th>USD</th><th>Tỷ giá</th><th>Doanh số VNĐ</th><th/></tr></thead><tbody>{orders.map(o=><tr key={o.id} className={o.isBounced?'bounced-order':''}><td><b>{o.customerName}</b><small>{o.date.split('-').reverse().join('/')}</small></td><td>{db.accounts.find(a=>a.id===o.accountId)?.ownerName}</td><td>{db.products.find(p=>p.id===o.productId)?.name}</td><td><span className={'status '+(isCareOrder(o)?'care':'done')}>{o.isBounced?'Bùng · Không tính':isCareOrder(o)?(o.type==='upsale'?'Chăm · Upsale':'Chăm sóc'):'Bán hàng'}</span></td><td>{countFormat(orderWeight(o))}{o.isSplit&&<small>Chia đơn</small>}</td><td>${money(o.amountUsd)}</td><td>{money(o.rate)}</td><td className="strong">{money(o.amountVnd)}</td><td><div className="row-actions"><ActionButton className="icon-btn" onClick={()=>setForm({...o,type:o.type==='care'?'sale':o.type,isCare:o.isCare===true||o.type==='care'})} aria-label="Sửa đơn"><Pencil size={15}/></ActionButton><ActionButton className="icon-btn" onClick={()=>setDeleting(o)} aria-label="Xóa đơn"><Trash2 size={15}/></ActionButton></div></td></tr>)}</tbody><tfoot><tr><td colSpan="7">Tổng doanh thu đã lọc</td><td>{money(orders.filter(o=>!o.isBounced).reduce((a,o)=>a+Number(o.amountVnd),0))}</td><td/></tr></tfoot></table>{!orders.length&&<div className="empty"><ShoppingBag/><p>Chưa có đơn hàng trong thời gian này.</p></div>}</div></div>
 {form&&<Modal title={form.id?'Chỉnh sửa đơn hàng':'Thêm đơn hàng'} onClose={()=>setForm(null)}><ActionForm onSubmit={async e=>{e.preventDefault();if(await mutate('saveOrder',form)){setForm(null);notify('Đã lưu đơn và cập nhật doanh thu.');}}}><div className="form-grid"><label>Ngày tính doanh số<DateField type="date" required value={form.date} onChange={e=>setForm({...form,date:e.target.value})}/></label>{user.role==='admin'&&<label>Account<select required value={form.accountId} onChange={e=>{const assignedProduct=db.products.find(p=>p.active&&db.assignments.some(a=>a.active&&a.accountId===e.target.value&&a.productId===p.id));setForm({...form,accountId:e.target.value,productId:assignedProduct?.id||'',amountUsd:form.amountUsd,rate:assignedProduct?.rate||22500});}}>{db.accounts.filter(a=>a.role==='user').map(a=><option key={a.id} value={a.id}>{a.ownerName}</option>)}</select></label>}<label>Sản phẩm<select required value={form.productId} onChange={e=>{const p=db.products.find(p=>p.id===e.target.value);setForm({...form,productId:p.id,rate:form.rate||p.rate});}}><option value="" disabled>Chọn sản phẩm</option>{[...new Map([...assigned.filter(p=>db.assignments.some(a=>a.active&&a.accountId===form.accountId&&a.productId===p.id)),...db.products.filter(p=>p.id===form.productId)].map(p=>[p.id,p])).values()].map(p=><option key={p.id} value={p.id}>{p.name}</option>)}</select></label><label>Tên khách hàng<input required value={form.customerName} onChange={e=>setForm({...form,customerName:e.target.value})}/></label><label>Loại đơn<select value={form.type} onChange={e=>setForm({...form,type:e.target.value})}><option value="sale">Bán hàng</option><option value="upsale">Upsale</option></select></label><label className="care-check"><input type="checkbox" checked={form.type==='upsale'||form.isCare===true} disabled={form.type==='upsale'} onChange={e=>setForm({...form,isCare:e.target.checked})}/> Đơn chăm</label><label className="care-check"><input type="checkbox" checked={form.isSplit===true} onChange={e=>setForm({...form,isSplit:e.target.checked})}/> Chia đơn (0,5 đơn)</label>{form.id&&<label className="care-check bounce-check"><input type="checkbox" checked={form.isBounced===true} onChange={e=>setForm({...form,isBounced:e.target.checked})}/> Bùng — không tính đơn và doanh số</label>}<label>Doanh số thực tế (USD)<NumberField placeholder="Nhập số tiền của đơn" type="number" min="0" step="0.01" required value={form.amountUsd} onChange={e=>setForm({...form,amountUsd:e.target.value===''?'':Number(e.target.value)})}/></label><label>Tỷ giá<NumberField type="number" min="1" required value={form.rate} onChange={e=>setForm({...form,rate:Number(e.target.value)})}/></label></div><p className="muted">Đơn upsale hoặc được tick “Đơn chăm” tính vào doanh thu chăm, không cộng vào doanh số bán hàng. Tick “Chia đơn” tính 0,5 đơn, không tick tính 1 đơn; doanh thu giữ nguyên số tiền nhập.</p><div className="calc-result"><span>Doanh số VNĐ</span><b>{money(form.amountUsd*form.rate)}đ</b></div><div className="modal-actions"><ActionButton type="button" className="btn" onClick={()=>setForm(null)}>Hủy</ActionButton><ActionButton className="btn primary" disabled={busy}>Lưu đơn hàng</ActionButton></div></ActionForm></Modal>}
 {deleting&&<Modal title="Xóa đơn hàng?" onClose={()=>setDeleting(null)}><p>Xóa đơn của {deleting.customerName}, doanh thu {money(deleting.amountVnd)}đ. Báo cáo sẽ được cập nhật.</p><div className="modal-actions"><ActionButton className="btn" onClick={()=>setDeleting(null)}>Hủy</ActionButton><ActionButton className="btn danger" disabled={busy} onClick={async()=>{if(await mutate('deleteOrder',{id:deleting.id,revision:deleting.revision||0})){setDeleting(null);notify('Đã xóa đơn hàng.');}}}>Xóa đơn</ActionButton></div></Modal>}
 {batch&&<BatchEntry kind="orders" products={assigned} accountId={user.id} mutate={mutate} notify={notify} onClose={()=>setBatch(false)}/>}</WindowGate>
 </>
}
function Targets({db,user,mutate,notify}){
 const [month,setMonth]=useState((user.role==='admin'?previousDay():dayString()).slice(0,7)),[account,setAccount]=useState(user.role==='admin'?db.accounts.find(a=>a.role==='user')?.id:user.id),[editing,setEditing]=useState(false),[draft,setDraft]=useState([]),[salary,setSalary]=useState(0);
 useEffect(()=>setEditing(false),[month,account]);
 const accountTargets=db.targets.filter(t=>t.accountId===account&&t.month===month).sort((a,b)=>(b.updatedAt||'').localeCompare(a.updatedAt||''));
 const summary=summarizeTargets(db,account,month);
 const products=summary.rows.map(r=>r.product);
 const sum={total:summary.total};
 const totalGoal=summary.total.goal,careGoal=summary.total.careGoal;
 function edit(){setDraft(products.filter(p=>user.role==='admin'?summary.rows.find(r=>r.product.id===p.id)?.editable:p.active&&db.assignments.some(a=>a.active&&a.accountId===user.id&&a.productId===p.id)).map(p=>{const t=accountTargets.find(t=>t.productId===p.id);return {productId:p.id,revision:t?.revision||0,revenue:t?.revenue||0,care:t?.care||0};}));setSalary(accountTargets[0]?.salary||0);setEditing(true);}
 return <><Heading eyebrow="KẾ HOẠCH & TIẾN ĐỘ" title="Mục tiêu tháng" description="Giá do admin quản lý. Số đơn và trung bình mỗi ngày được tính tự động.">{<ActionButton className="btn primary" disabled={!containsRange(db.scope,periodRange('month','','','',month))} onClick={edit}><Pencil size={16}/> Nhập / Sửa mục tiêu</ActionButton>}</Heading><div className="panel entry-toolbar"><label>Tháng mục tiêu<DateField type="month" value={month} onChange={e=>setMonth(e.target.value)}/></label>{user.role==='admin'&&<label>Account<select value={account} onChange={e=>setAccount(e.target.value)}>{db.accounts.filter(a=>a.role==='user').map(a=><option key={a.id} value={a.id}>{a.ownerName}</option>)}</select></label>}<div className="entry-meta"><b>{db.accounts.find(a=>a.id===account)?.ownerName}</b><span>Giá được giữ theo kỳ mục tiêu đã lưu</span></div></div><WindowGate range={periodRange('month','','','',month)}><div className="stats three"><article className="stat"><div className="stat-top">Mục tiêu lương <Wallet size={18}/></div><div className="stat-value">{money(accountTargets[0]?.salary||0)}<small>đ</small></div><p className="stat-sub">Mục tiêu tham khảo, chưa quy đổi thành lương thực nhận</p></article><article className="stat"><div className="stat-top">Mục tiêu doanh thu <Target size={18}/></div><div className="stat-value">{money(totalGoal)}<small>đ</small></div><div className="progress-track"><i style={{width:Math.min(100,divide(sum.total.revenue,totalGoal)*100)+'%'}}/></div><div className="stat-sub">Đã đạt {pct(divide(sum.total.revenue,totalGoal))} · {money(sum.total.revenue)}đ</div></article><article className="stat"><div className="stat-top">Mục tiêu doanh thu chăm <MessageSquare size={18}/></div><div className="stat-value">{money(careGoal)}<small>đ</small></div><div className="progress-track purple-track"><i style={{width:Math.min(100,divide(sum.total.care,careGoal)*100)+'%'}}/></div><div className="stat-sub">Đã đạt {pct(divide(sum.total.care,careGoal))} · {money(sum.total.care)}đ</div></article></div><div className="panel"><div className="panel-heading"><div><h2>Từ mục tiêu đến kết quả</h2><p>Số đơn làm tròn lên · Chia đúng số ngày thực tế trong tháng</p></div><span className="tag">{products.length} sản phẩm</span></div><TargetsTable summary={summary}/></div>
 {editing&&<Modal title="Đặt mục tiêu tháng" onClose={()=>setEditing(false)}><ActionForm onSubmit={async e=>{e.preventDefault();if(await mutate('saveTargets',{month,accountId:account,targets:draft,salary})){setEditing(false);notify('Đã lưu mục tiêu tháng.');}}}><label>Mục tiêu lương (VNĐ)<NumberField type="number" min="0" value={salary} onChange={e=>setSalary(Number(e.target.value))}/></label><p className="muted">Chỉ nhập các mức doanh thu. Giá và số đơn được tính từ danh mục sản phẩm.</p>{draft.map((t,i)=><div className="target-edit-row" key={t.productId}><b>{db.products.find(p=>p.id===t.productId)?.name}</b><label>Mục tiêu doanh thu<NumberField type="number" min="0" required value={t.revenue} onChange={e=>setDraft(draft.map((x,j)=>j===i?{...x,revenue:Number(e.target.value)}:x))}/></label><label>Mục tiêu chăm<NumberField type="number" min="0" required value={t.care} onChange={e=>setDraft(draft.map((x,j)=>j===i?{...x,care:Number(e.target.value)}:x))}/></label></div>)}<div className="modal-actions"><ActionButton className="btn" type="button" onClick={()=>setEditing(false)}>Hủy</ActionButton><ActionButton className="btn primary">Lưu mục tiêu</ActionButton></div></ActionForm></Modal>}
 </WindowGate></>
}
function Products({db,mutate,notify}){const [form,setForm]=useState(null),[batch,setBatch]=useState(false);return <><Heading eyebrow="QUẢN TRỊ" title="Sản phẩm & giá bán" description="Danh mục chung do admin quản lý. User chỉ thấy sản phẩm được phân phối."><ActionButton className="btn primary" onClick={()=>{if(window.matchMedia('(min-width: 769px)').matches)setBatch(true);else setForm({name:'',priceUsd:'',rate:22500,active:true,color:'#18765c'});}}><Plus size={17}/> Thêm sản phẩm</ActionButton></Heading><div className="product-grid">{db.products.map(p=><article className="panel product-card" key={p.id}><div className="product-card-top"><span className="product-mark" style={{background:p.color||'#18765c'}}>{p.name[0]}</span><span className={'status '+(p.active?'done':'draft')}>{p.active?'Đang sử dụng':'Ngừng dùng'}</span></div><h2>{p.name}</h2><div className="product-price">${money(p.priceUsd)}<small>{money(p.priceUsd*p.rate)}đ</small></div><p className="muted">Tỷ giá: {money(p.rate)}đ / USD</p><div className="product-card-foot"><span><Users size={15}/> {db.assignments.filter(a=>a.productId===p.id&&a.active).length} account</span><ActionButton className="text-btn" onClick={()=>setForm({...p})}>Chỉnh sửa <ArrowUpRight size={14}/></ActionButton></div></article>)}</div>{form&&<Modal title={form.id?'Chỉnh sửa sản phẩm':'Thêm sản phẩm'} onClose={()=>setForm(null)}><ActionForm onSubmit={async e=>{e.preventDefault();if(await mutate('saveProduct',form)){setForm(null);notify('Đã lưu sản phẩm.');}}}><div className="form-grid"><label>Tên sản phẩm<input required value={form.name} onChange={e=>setForm({...form,name:e.target.value})}/></label><label>Giá USD<NumberField required type="number" step="0.01" min="0.01" value={form.priceUsd} onChange={e=>setForm({...form,priceUsd:Number(e.target.value)})}/></label><label>Tỷ giá<NumberField required type="number" min="1" value={form.rate} onChange={e=>setForm({...form,rate:Number(e.target.value)})}/></label><label>Trạng thái<select value={String(form.active)} onChange={e=>setForm({...form,active:e.target.value==='true'})}><option value="true">Đang sử dụng</option><option value="false">Ngừng sử dụng</option></select></label></div><div className="calc-result"><span>Giá VNĐ</span><b>{money(form.priceUsd*form.rate)}đ</b></div><div className="modal-actions"><ActionButton className="btn" type="button" onClick={()=>setForm(null)}>Hủy</ActionButton><ActionButton className="btn primary">Lưu sản phẩm</ActionButton></div></ActionForm></Modal>}{batch&&<BatchEntry kind="products" mutate={mutate} notify={notify} onClose={()=>setBatch(false)}/>}</>}
function Accounts({db,mutate,notify}){const [form,setForm]=useState(null),[deleting,setDeleting]=useState(null),[archived,setArchived]=useState(false);return <><Heading eyebrow="QUẢN TRỊ" title="Account & phân phối" description="Giao đúng sản phẩm cho đúng người. Dữ liệu của mỗi account được tách riêng."><ActionButton className="btn primary" onClick={()=>setForm({ownerName:'',username:'',password:'',role:'user'})}><Plus size={17}/> Tạo account</ActionButton></Heading><section className="panel"><div className="panel-heading"><div><h2>Phân phối sản phẩm</h2><p>Bật để account có thể điền và gửi dữ liệu cho sản phẩm</p></div><label className="care-check"><input type="checkbox" checked={archived} onChange={e=>setArchived(e.target.checked)}/> Hiện user đã xóa</label></div><div className="table-scroll"><table className="assignment-table"><thead><tr><th>Chủ sở hữu / Account</th>{db.products.filter(p=>p.active).map(p=><th key={p.id}>{p.name}</th>)}</tr></thead><tbody>{db.accounts.filter(a=>archived||!a.deletedAt).map(a=><tr key={a.id}><td><span className="account-cell"><span className="avatar small-avatar">{a.ownerName[0]}</span><span><b>{a.ownerName}</b><small>@{a.username} · {a.role==='admin'?'Admin':'User'}</small></span>{a.deletedAt?<ActionButton className="btn" onClick={async()=>{if(await mutate('restoreAccount',{id:a.id}))notify('Đã khôi phục user. Giao lại sản phẩm để bắt đầu nhập liệu.');}}>Khôi phục</ActionButton>:<><ActionButton className="icon-btn" aria-label={'Sửa account '+a.ownerName} onClick={()=>setForm({...a,password:''})}><Pencil size={14}/></ActionButton>{a.role==='user'&&<ActionButton className="icon-btn" aria-label={'Xóa user '+a.ownerName} onClick={()=>setDeleting(a)}><Trash2 size={14}/></ActionButton>}</>}</span></td>{a.deletedAt?<td colSpan={Math.max(1,db.products.filter(p=>p.active).length)} className="admin-access-cell">Đã xóa · Đã khóa đăng nhập</td>:a.role==='admin'?<td colSpan={Math.max(1,db.products.filter(p=>p.active).length)} className="admin-access-cell">Admin được xem tất cả sản phẩm</td>:db.products.filter(p=>p.active).map(p=>{const active=db.assignments.some(x=>x.accountId===a.id&&x.productId===p.id&&x.active);return <td key={p.id}><ActionButton role="switch" aria-checked={active} aria-label={a.ownerName+' — '+p.name} className={'switch '+(active?'on':'')} onClick={async()=>{if(await mutate('assign',{accountId:a.id,productId:p.id,active:!active}))notify(active?'Đã thu hồi quyền nhập sản phẩm.':'Đã phân phối sản phẩm.');}}><span/></ActionButton></td>})}</tr>)}</tbody></table></div><div className="table-note">Bấm biểu tượng bút để sửa account và vai trò. Admin cuối cùng không thể bị hạ quyền. Đổi role sẽ đăng xuất các phiên cũ của account đó.</div></section>{form&&<Modal title={form.id?'Chỉnh sửa account':'Tạo account mới'} onClose={()=>setForm(null)}><ActionForm onSubmit={async e=>{e.preventDefault();if(await mutate('saveAccount',form)){setForm(null);notify('Đã lưu account.');}}}><div className="form-grid"><label>Tên chủ sở hữu<input required value={form.ownerName} onChange={e=>setForm({...form,ownerName:e.target.value})}/></label><label>Tên đăng nhập<input required pattern="[a-zA-Z0-9_.-]+" value={form.username} onChange={e=>setForm({...form,username:e.target.value})}/></label><label>Vai trò<select value={form.role||'user'} onChange={e=>setForm({...form,role:e.target.value})}><option value="user">User — chỉ sản phẩm được giao</option><option value="admin">Admin — quản lý toàn bộ</option></select></label><label>Mật khẩu {form.id?'mới (để trống nếu giữ nguyên)':''}<input type="password" autoComplete="new-password" required={!form.id} minLength={10} value={form.password} onChange={e=>setForm({...form,password:e.target.value})}/></label></div><div className="modal-actions"><ActionButton type="button" className="btn" onClick={()=>setForm(null)}>Hủy</ActionButton><ActionButton className="btn primary">Lưu account</ActionButton></div></ActionForm></Modal>}{deleting&&<Modal title="Xóa user?" onClose={()=>setDeleting(null)}><p>Xóa tài khoản <b>{deleting.ownerName} (@{deleting.username})</b> sẽ khóa đăng nhập và thu hồi các phiên cũ. Báo cáo, đơn hàng và lịch sử vẫn được giữ.</p><div className="modal-actions"><ActionButton type="button" className="btn" onClick={()=>setDeleting(null)}>Hủy</ActionButton><ActionButton className="btn danger" onClick={async()=>{if(await mutate('deleteAccount',{id:deleting.id})){setDeleting(null);notify('Đã xóa user, dữ liệu lịch sử được giữ nguyên.');}}}>Xóa user</ActionButton></div></Modal>}</>}
function SettingsPage(){return <><Heading eyebrow="HỆ THỐNG" title="Kết nối Google Sheets" description="Cấu hình tập trung trong một file. Sẵn sàng chuyển từ dữ liệu mẫu sang dữ liệu thật."/><div className="settings-grid"><section className="panel settings-card"><span className="settings-icon"><FileText size={25}/></span><h2>Một file cấu hình</h2><p>Chỉnh <code>public/config.js</code> trong mã nguồn. File này chứa link Sheet, địa chỉ Apps Script và chế độ hoạt động.</p><pre>{`window.APP_CONFIG = {\n  sheetUrl: 'https://docs.google.com/spreadsheets/d/...',\n  apiUrl: 'https://script.google.com/macros/s/.../exec',\n  currency: 'VND'\n};`}</pre><div className="config-status"><span>Google Sheet</span><b>{config.sheetUrl?'Đã điền link':'Chưa cấu hình'}</b></div><div className="config-status"><span>Apps Script API</span><b>{config.apiUrl?'Đã điền link':'Chưa cấu hình'}</b></div>{config.sheetUrl&&/^https:\/\/docs\.google\.com\/spreadsheets\//.test(config.sheetUrl)&&<a className="btn" href={config.sheetUrl} target="_blank" rel="noreferrer">Mở Google Sheet <ExternalLink size={15}/></a>}</section><section className="panel settings-card"><h2>Kết nối trong 4 bước</h2><ol className="setup-steps"><li><span>01</span><div><b>Mở Apps Script từ Sheet</b><p>Tiện ích mở rộng → Apps Script. Dán file backend/Code.gs đi kèm mã nguồn.</p></div></li><li><span>02</span><div><b>Khởi tạo và tạo admin</b><p>Chạy setup(), sau đó tạo admin qua createInitialAdmin(). Các bảng SL_* được tạo riêng.</p></div></li><li><span>03</span><div><b>Triển khai Web App</b><p>Chạy dưới quyền chủ Sheet, cho phép truy cập Web App. API vẫn kiểm tra phiên và quyền account.</p></div></li><li><span>04</span><div><b>Điền config và chạy web</b><p>Dán URL API vào config.js hoặc SO_LIEU_API_URL trên Vercel rồi build lại.</p></div></li></ol><div className="info-note">Bản hiện tại: đang dùng API đã cấu hình.</div></section></div></>}
createRoot(document.getElementById('root')).render(<OperationsProvider><App/></OperationsProvider>);
